import{_ as e,o as i,c as s,a2 as r}from"./chunks/framework.CDpkVv68.js";const m=JSON.parse('{"title":"Guía de Syrolands","description":"","frontmatter":{},"headers":[],"relativePath":"es/guide/index.md","filePath":"es/guide/index.md"}'),o={name:"es/guide/index.md"};function n(t,a,d,l,c,u){return i(),s("div",null,[...a[0]||(a[0]=[r('<h1 id="syrolands-guide" tabindex="-1">Guía de Syrolands <a class="header-anchor" href="#syrolands-guide" aria-label="Enlace permanente a &quot;Guía de Syrolands&quot;">​</a></h1><h2 id="tl-dr" tabindex="-1">TL;DR <a class="header-anchor" href="#tl-dr" aria-label="Enlace permanente a &quot;TL;DR&quot;">​</a></h2><ul><li>Empieza por la Introducción para conocer los pilares de mundo, combate, conocimiento y artesanía.</li><li>Elige un sistema para leer una guía breve y después consulta su diseño detallado correspondiente.</li><li>Revisa el estado de cada función: intención aprobada, mecánicas propuestas y disponibilidad comprobada son cosas distintas.</li></ul><p>Una introducción breve a Syrolands para amigos, personas que prueban el juego y futuros jugadores. El Lab contiene ideas aceptadas, experimentos y propuestas; describir un sistema aquí no significa que esté disponible para jugar.</p><h2 id="start-here" tabindex="-1">Empieza aquí <a class="header-anchor" href="#start-here" aria-label="Enlace permanente a &quot;Empieza aquí&quot;">​</a></h2><p>La <a href="/Syrolands-Public/es/guide/introduction.html">Introducción: un mundo vivo que toma forma con sus habitantes</a> presenta los pilares del diseño antes de los sistemas individuales.</p><h2 id="characters" tabindex="-1">Personajes <a class="header-anchor" href="#characters" aria-label="Enlace permanente a &quot;Personajes&quot;">​</a></h2><p><a href="/Syrolands-Public/es/guide/characters/progression.html">Progresión del personaje</a> · <a href="/Syrolands-Public/es/guide/characters/skills.html">Habilidades, límite de puntos y maestros</a> · <a href="/Syrolands-Public/es/guide/characters/techniques.html">Técnicas y especializaciones</a> · <a href="/Syrolands-Public/es/guide/characters/character-creation.html">Creación de personajes y trasfondos</a> · <a href="/Syrolands-Public/es/guide/characters/stats.html">Atributos</a>.</p><p>Estas direcciones con estado Propuesto buscan personajes útiles desde el inicio, especialización significativa y controles ágiles; no son cambios confirmados en el juego disponible.</p><h2 id="combat" tabindex="-1">Combate <a class="header-anchor" href="#combat" aria-label="Enlace permanente a &quot;Combate&quot;">​</a></h2><p>La <a href="/Syrolands-Public/es/guide/combat/overview.html">visión del combate</a> explica la dirección Modern con estado Propuesto, la alternativa Legacy y las lesiones locales, distinguiendo los experimentos de la experiencia deseada.</p><p><a href="/Syrolands-Public/es/guide/combat/limbs-and-trauma.html">Extremidades y trauma</a> · <a href="/Syrolands-Public/es/guide/combat/weapons-and-damage.html">Armas y tipos de daño</a> · <a href="/Syrolands-Public/es/guide/combat/armor-and-protection.html">Armadura y protección</a> · <a href="/Syrolands-Public/es/guide/combat/targeting-and-anatomy.html">Ataques dirigidos y Anatomy</a> · <a href="/Syrolands-Public/es/guide/combat/stamina-and-reactive-combat.html">Stamina y recuperación</a>.</p><h2 id="magic" tabindex="-1">Magia <a class="header-anchor" href="#magic" aria-label="Enlace permanente a &quot;Magia&quot;">​</a></h2><p><a href="/Syrolands-Public/es/guide/magic/overview.html">Magery</a> · <a href="/Syrolands-Public/es/guide/magic/learning-spells.html">Aprender hechizos</a> · <a href="/Syrolands-Public/es/guide/magic/memory-and-familiarity.html">Memoria de hechizos y Familiarity</a> · <a href="/Syrolands-Public/es/guide/magic/meditation-and-concentration.html">Meditation y Concentration</a> · <a href="/Syrolands-Public/es/guide/magic/spellbooks-scrolls-and-reagents.html">Libros de hechizos, pergaminos y reactivos</a> · <a href="/Syrolands-Public/es/guide/magic/variants-and-glyphs.html">Variantes y glifos</a>.</p><p>El modelo mágico con estado Propuesto separa conocimiento, ejecución, práctica y preparación. Estas páginas no acreditan una experiencia de juego ya disponible.</p><h2 id="professions" tabindex="-1">Profesiones <a class="header-anchor" href="#professions" aria-label="Enlace permanente a &quot;Profesiones&quot;">​</a></h2><p>La <a href="/Syrolands-Public/es/guide/professions/overview.html">visión de las profesiones</a> presenta el rediseño con estado Propuesto: oficios integrados en la aventura, aprendizaje, diarios, producción y reputación.</p><p><a href="/Syrolands-Public/es/guide/professions/cooking.html">Cooking</a> · <a href="/Syrolands-Public/es/guide/professions/alchemy.html">Alchemy</a> · <a href="/Syrolands-Public/es/guide/professions/mining.html">Mining</a> · <a href="/Syrolands-Public/es/guide/professions/blacksmithing.html">Blacksmithing</a> · <a href="/Syrolands-Public/es/guide/professions/tailoring.html">Tailoring</a> · <a href="/Syrolands-Public/es/guide/professions/lumberjacking.html">Lumberjacking</a> · <a href="/Syrolands-Public/es/guide/professions/carpentry.html">Carpentry</a> · <a href="/Syrolands-Public/es/guide/professions/tinkering.html">Tinkering</a> · <a href="/Syrolands-Public/es/guide/professions/inscription.html">Inscription</a>. Bowmaking es una vía de técnicas dentro de Carpentry.</p><h2 id="items" tabindex="-1">Objetos <a class="header-anchor" href="#items" aria-label="Enlace permanente a &quot;Objetos&quot;">​</a></h2><p><a href="/Syrolands-Public/es/guide/items/item-quality.html">Calidad de los objetos / Masterworks</a> explica categorías de calidad con estado Propuesto, materiales, rasgos raros e historia de los objetos.</p><h2 id="more-systems" tabindex="-1">Más sistemas <a class="header-anchor" href="#more-systems" aria-label="Enlace permanente a &quot;Más sistemas&quot;">​</a></h2><p>Las guías para jugadores ampliarán Mundo y Sociedad / Economía cuando exista material de referencia adecuado. Estas categorías no implican páginas vacías ni mecánicas aprobadas.</p><p>Para consultar el contenido detallado existente, utiliza el <a href="/Syrolands-Public/es/game-design/">índice de Diseño del juego</a>.</p><h2 id="reading-feature-status" tabindex="-1">Cómo interpretar los estados <a class="header-anchor" href="#reading-feature-status" aria-label="Enlace permanente a &quot;Cómo interpretar los estados&quot;">​</a></h2><p><strong>Propuesto</strong> significa una idea candidata; <strong>Aceptado</strong>, una intención aprobada. <strong>Experimental</strong> señala investigaciones y prototipos. <strong>Implementado</strong> identifica código existente con un alcance indicado. La disponibilidad y la verificación se indican por separado: estar implementado no garantiza una función disponible ni completamente probada. Estas etiquetas describen el contenido, no garantizan su disponibilidad actual.</p><h2 id="combat-actions-and-practice-—-proposed" tabindex="-1">Acciones de combate y práctica — Propuesto <a class="header-anchor" href="#combat-actions-and-practice-—-proposed" aria-label="Enlace permanente a &quot;Acciones de combate y práctica — Propuesto&quot;">​</a></h2><p><a href="/Syrolands-Public/es/guide/combat/legacy-and-modern.html">Legacy y Modern</a> · <a href="/Syrolands-Public/es/guide/combat/special-attacks.html">Special Attacks</a> · <a href="/Syrolands-Public/es/guide/combat/flow.html">Flow</a> · <a href="/Syrolands-Public/es/guide/combat/reach-and-spacing.html">Alcance y distancia</a> · <a href="/Syrolands-Public/es/guide/characters/familiarity.html">Familiarity</a>.</p><p>El <a href="/Syrolands-Public/es/game-design/combat/variable-registry.html">Registro de variables de combate</a> reúne definiciones antes de ajustar cifras; no acredita nuevos modos ni acciones jugables.</p><h2 id="three-weapon-test-profile" tabindex="-1">Perfil de prueba de tres armas <a class="header-anchor" href="#three-weapon-test-profile" aria-label="Enlace permanente a &quot;Perfil de prueba de tres armas&quot;">​</a></h2><p><a href="/Syrolands-Public/es/guide/combat/numeric-prototype.html">Longsword, Spear y War Hammer</a> ya tienen cifras con estado Experimental para un futuro prototipo. No están implementadas ni representan un equilibrio definitivo.</p>',30)])])}const h=e(o,[["render",n]]);export{m as __pageData,h as default};
